*** End Patch
*** Begin Patch
*** Update File: src/Fixer/Whitespace/StatementIndentationFixer.php
@@
     private function findStatementEndIndex(Tokens $tokens, int $index, int $parentScopeEndIndex): int
@@
         return $endIndex ?? $tokens->getPrevMeaningfulToken($parentScopeEndIndex);
     }
+
+    private function findControlStructureEndIndex(Tokens $tokens, int $index, int $signatureEndIndex): int
+    {
+        $bodyStartIndex = $tokens->getNextMeaningfulToken($signatureEndIndex);
+
+        if (null === $bodyStartIndex) {
+            return $signatureEndIndex;
+        }
+
+        if ($tokens[$bodyStartIndex]->equals('{')) {
+            $bodyEndIndex = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_CURLY_BRACE, $bodyStartIndex);
+        } else {
+            $bodyEndIndex = $this->findStatementEndIndex($tokens, $bodyStartIndex, \count($tokens) - 1);
+        }
+
+        $nextIndex = $tokens->getNextMeaningfulToken($bodyEndIndex);
+        if (null !== $nextIndex && $tokens[$nextIndex]->isGivenKind([T_ELSE, T_ELSEIF])) {
+            return $this->findControlStructureEndIndex($tokens, $nextIndex, $nextIndex);
+        }
+
+        return $bodyEndIndex;
+    }
*** End Patch

