private function findStatementEndIndex(Tokens $tokens, int $index, int $parentScopeEndIndex): int
{
    $endIndex = null;
    $blockEdgeDefinitions = Tokens::getBlockEdgeDefinitions();
    $parenthesisEdges = $blockEdgeDefinitions[Tokens::BLOCK_TYPE_PARENTHESIS_BRACE];
    $curlyBraceEdges = $blockEdgeDefinitions[Tokens::BLOCK_TYPE_CURLY_BRACE];
    $arraySquareBraceEdges = $blockEdgeDefinitions[Tokens::BLOCK_TYPE_ARRAY_SQUARE_BRACE];
    $parenthesisStartEdge = $parenthesisEdges['start'];
    $parenthesisEndEdge = $parenthesisEdges['end'];
    $curlyStartEdge = $curlyBraceEdges['start'];
    $curlyEndEdge = $curlyBraceEdges['end'];
    $arrayStartEdge = $arraySquareBraceEdges['start'];
    $arrayEndEdge = $arraySquareBraceEdges['end'];
    $tokenCount = \count($tokens);
    $lastTokenIndex = $tokenCount - 1;
    $whitespaceCharacters = " \t\n\r\0\x0B";
    $whitespaceTokenPrototype = [T_WHITESPACE];
    $arraySquareOpenPrototype = [CT::T_ARRAY_SQUARE_BRACE_OPEN];
    $statementTerminatorPrototypes = [';', ',', '}', [T_CLOSE_TAG]];

    for ($searchEndIndex = $index; $searchEndIndex <= $parentScopeEndIndex; ++$searchEndIndex) {
        $searchEndToken = $tokens[$searchEndIndex];
        $blockStartEdge = null;
        $blockEndEdge = null;

        if ($searchEndToken->equals($parenthesisStartEdge)) {
            $blockStartEdge = $parenthesisStartEdge;
            $blockEndEdge = $parenthesisEndEdge;
        } elseif ($searchEndToken->equals($curlyStartEdge)) {
            $blockStartEdge = $curlyStartEdge;
            $blockEndEdge = $curlyEndEdge;
        } elseif ($searchEndToken->equals($arraySquareOpenPrototype)) {
            $blockStartEdge = $arrayStartEdge;
            $blockEndEdge = $arrayEndEdge;
        }

        if (null !== $blockStartEdge) {
            $blockLevel = 0;
            $blockIndex = $searchEndIndex;

            if (!$tokens[$blockIndex]->equals($blockStartEdge)) {
                $invalidStartToken = $tokens[$blockIndex];
                $invalidStartLabel = $invalidStartToken->getContent();

                throw new \InvalidArgumentException(sprintf('Invalid param $startIndex - not a proper block "start", got "%s".', $invalidStartLabel));
            }

            for (; $blockIndex !== $lastTokenIndex; ++$blockIndex) {
                $blockToken = $tokens[$blockIndex];

                if ($blockToken->equals($blockStartEdge)) {
                    ++$blockLevel;

                    continue;
                }

                if (!$blockToken->equals($blockEndEdge)) {
                    continue;
                }

                --$blockLevel;

                if (0 === $blockLevel) {
                    break;
                }
            }

            if (!$tokens[$blockIndex]->equals($blockEndEdge)) {
                $missingEndToken = $tokens[$blockIndex];
                $missingEndLabel = $missingEndToken->getContent();

                throw new \UnexpectedValueException(sprintf('Missing block "end", got "%s".', $missingEndLabel));
            }

            $searchEndIndex = $blockIndex;

            continue;
        }

        if (!$searchEndToken->equalsAny($statementTerminatorPrototypes)) {
            continue;
        }

        $previousIndex = $searchEndIndex;
        $previousNonWhitespaceIndex = null;

        while (true) {
            --$previousIndex;

            if (!$tokens->offsetExists($previousIndex)) {
                break;
            }

            $previousToken = $tokens[$previousIndex];
            $previousContent = $previousToken->getContent();
            $previousIsArrayToken = $previousToken->isArray();
            $previousIsWhitespaceKind = $previousToken->equals($whitespaceTokenPrototype);

            if ($previousIsArrayToken && !$previousIsWhitespaceKind) {
                $previousNonWhitespaceIndex = $previousIndex;

                break;
            }

            if ('' !== trim($previousContent, $whitespaceCharacters)) {
                $previousNonWhitespaceIndex = $previousIndex;

                break;
            }
        }

        $endIndex = $previousNonWhitespaceIndex;

        break;
    }

    return $endIndex ?? $tokens->getPrevMeaningfulToken($parentScopeEndIndex);
}

private function findControlStructureEndIndex(Tokens $tokens, int $index): int
{
    if ($tokens[$index]->isGivenKind([T_ELSE, T_DO])) {
        $bodyStartIndex = $tokens->getNextMeaningfulToken($index);
    } else {
        $parenthesisIndex = $tokens->getNextMeaningfulToken($index);
        $bodyStartIndex = $tokens->getNextMeaningfulToken(
            $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $parenthesisIndex)
        );
    }

    if ($tokens[$bodyStartIndex]->equals('{')) {
        $bodyEndIndex = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_CURLY_BRACE, $bodyStartIndex);
